window.CARDS=window.CARDS||{};CARDS["people-nagumo-miyabi"]=[{"i":"sc-nagumo-miyabi-y1v4_5-p72-1","v":"y1v4.5","y":1,"o":5,"k":"","w":"horikita-manabu nagumo-miyabi","q":"nagumo miyabi ch 3  a passing mention named for the first time in this volume  tachibana says next year s change means nagumo kun s election as student council president  manabu frames the coming school change as something he will need power to combat  tachibana reads it as the nagumo presidency  ak has never heard the name from any first year and infers nagumo is a second year","h":"<article class=\"card\" id=\"sc-nagumo-miyabi-y1v4_5-p72-1\"><h3><span class=\"ttl\">Ch.3: a passing mention<\/span><span class=\"meta\">Y1V4.5 · p.72<\/span><\/h3><p class=\"setup\">Named for the first time in this volume: Tachibana says next year&#x27;s change means Nagumo-kun&#x27;s election as student council president.<\/p><p class=\"with\">with <a href=\"horikita-manabu.html\">Horikita Manabu<\/a><\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Manabu<\/b> Manabu frames the coming school change as something he will need power to combat; Tachibana reads it as the Nagumo presidency.<span class=\"pg\">p.72<\/span><\/li><li><span class=\"mlabel\">Inference, not stated<\/span> AK has never heard the name from any first-year and infers Nagumo is a second-year.<span class=\"pg\">p.72<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nagumo-miyabi-y1v4_5-p177-1\">→ After: Ch.6: the vice president&#x27;s show<\/button><\/div><\/article>"},{"i":"sc-nagumo-miyabi-y1v4_5-p177-1","v":"y1v4.5","y":1,"o":5,"k":"","w":"horikita-suzune ichinose-honami nagumo-miyabi","q":"nagumo miyabi ch 6  the vice president s show the blond player the crowd cheers is nagumo miyabi  a second year class a student and student council vice president who dominates the pool volleyball game  his volleyball spike dominates the game by himself  the girls  high pitched cheers drown out the other matches going on at the same time  kushida names him nagumo senpai from class a  a second year who is really popular with the girls  ichinose adds that he is the current student council vice president  said to take over as president next year  and really smart  every time he shows off  her shoulders tighten slightly at the student council connection  during the student council elections president horikita and nagumo both ran for president  when nagumo was just a first year student  the final decision on ichinose s application came from nagumo  she heard president horikita seemed disappointed in this year s first year students  she models her goal on him   both rose from class b   and says she will become president after him  then adds she was just kidding  she calls his potential limited and his start delayed  he is the reason her shoulders tighten at the student council words  the earring visible on him is a clip on  ichinose says he dresses normally in school  ichinose believes president horikita might be stepping down in october  leaving nagumo next in line","h":"<article class=\"card\" id=\"sc-nagumo-miyabi-y1v4_5-p177-1\"><h3><span class=\"ttl\">Ch.6: the vice president&#x27;s show<\/span><span class=\"meta\">Y1V4.5 · p.177–182<\/span><\/h3><p class=\"setup\">The blond player the crowd cheers is Nagumo Miyabi, a second-year Class A student and student council vice president who dominates the pool volleyball game.<\/p><p class=\"with\">with <a href=\"horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"ichinose-honami.html\">Ichinose Honami<\/a><\/p><details class=\"more\"><summary>10 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Feat<\/span> His volleyball spike dominates the game by himself; the girls&#x27; high-pitched cheers drown out the other matches going on at the same time.<span class=\"pg\">p.178<\/span><\/li><li><span class=\"mlabel\">Fact<\/span> Kushida names him Nagumo-senpai from Class A, a second year who is really popular with the girls.<span class=\"pg\">p.179<\/span><\/li><li><span class=\"mlabel\">Fact<\/span> Ichinose adds that he is the current student council vice president, said to take over as president next year, and really smart.<span class=\"pg\">p.179<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Every time he shows off, her shoulders tighten slightly at the student council connection.<span class=\"pg\">p.179<\/span><\/li><li><span class=\"mlabel\">Fact<\/span> During the student council elections President Horikita and Nagumo both ran for president, when Nagumo was just a first-year student.<span class=\"pg\">p.180<\/span><\/li><li><span class=\"mlabel\">Fact<\/span> The final decision on Ichinose&#x27;s application came from Nagumo; she heard President Horikita seemed disappointed in this year&#x27;s first-year students.<span class=\"pg\">p.180<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> She models her goal on him — both rose from Class B — and says she will become president after him, then adds she was just kidding.<span class=\"pg\">p.180<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> She calls his potential limited and his start delayed; he is the reason her shoulders tighten at the student council words.<span class=\"pg\">p.181<\/span><\/li><li><span class=\"mlabel\">Detail<\/span> The earring visible on him is a clip-on; Ichinose says he dresses normally in school.<span class=\"pg\">p.182<\/span><\/li><li><span class=\"mlabel\">Position<\/span> Ichinose believes President Horikita might be stepping down in October, leaving Nagumo next in line.<span class=\"pg\">p.180<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nagumo-miyabi-y1v4_5-p72-1\">← Before: Ch.3: a passing mention<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nagumo-miyabi-y1v4_5-p185-1\">→ After: Ch.6: a passing mention<\/button><\/div><\/article>"},{"i":"sc-nagumo-miyabi-y1v4_5-p185-1","v":"y1v4.5","y":1,"o":5,"k":"","w":"nagumo-miyabi","q":"nagumo miyabi ch 6  a passing mention sudou s spike power is measured against nagumo s during the volleyball game","h":"<article class=\"card\" id=\"sc-nagumo-miyabi-y1v4_5-p185-1\"><h3><span class=\"ttl\">Ch.6: a passing mention<\/span><span class=\"meta\">Y1V4.5 · p.185<\/span><\/h3><p class=\"setup\">Sudou&#x27;s spike power is measured against Nagumo&#x27;s during the volleyball game.<\/p><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nagumo-miyabi-y1v4_5-p177-1\">← Before: Ch.6: the vice president&#x27;s show<\/button><\/div><\/article>"},{"i":"sc-nagumo-miyabi-y1v5-p68-1","v":"y1v5","y":1,"o":6,"k":"spoken","w":"kushida-kikyou horikita-suzune horikita-manabu nagumo-miyabi","q":"nagumo miyabi ch 5  5  the practice pitch nagumo strolls onto the soccer pitch mid practice and is greeted by kushida by nickname   i see you re on a date   we don t really hold back here  so i think this is a good way to measure our players  strengths  calls her  kikyou chan  and winks before rejoining the game  outclasses both hirata and shibata in the practice game  then scores from midfield    in a different league  horikita refuses to concede the skill   he s just really athletic  that s all  introduced as the candidate to be next student council president  abilities on par with horikita s older brother","h":"<article class=\"card\" id=\"sc-nagumo-miyabi-y1v5-p68-1\"><h3><span class=\"ttl\">Ch.5 §5: The practice pitch<\/span><span class=\"meta\">Y1V5 · p.68–85<\/span><\/h3><p class=\"setup\">Nagumo strolls onto the soccer pitch mid-practice and is greeted by Kushida by nickname.<\/p><p class=\"with\">with <a href=\"kushida-kikyou.html\">Kushida Kikyō<\/a> · <a href=\"horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"horikita-manabu.html\">Horikita Manabu<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“I see you’re on a date.”<span class=\"pg\">p.76<\/span><\/li><li class=\"q spoken\">“We don’t really hold back here, so I think this is a good way to measure our players’ strengths,”<span class=\"pg\">p.76<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kushida Kikyō<\/b> Calls her “Kikyou-chan” and winks before rejoining the game.<span class=\"pg\">p.76<\/span><\/li><li><span class=\"mlabel\">Feat<\/span> Outclasses both Hirata and Shibata in the practice game, then scores from midfield — “in a different league.”<span class=\"pg\">p.77<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Horikita refuses to concede the skill: “He’s just really athletic, that’s all.”<span class=\"pg\">p.77<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Manabu<\/b> Introduced as the candidate to be next student council president, abilities on par with Horikita’s older brother.<span class=\"pg\">p.76<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nagumo-miyabi-y1v5-p79-1\">→ After: Ch.5, Ch.9: passing mentions<\/button><\/div><\/article>"},{"i":"sc-nagumo-miyabi-y1v5-p79-1","v":"y1v5","y":1,"o":6,"k":"","w":"nagumo-miyabi","q":"nagumo miyabi ch 5  ch 9  passing mentions second year soccer players take a break  nagumo calls to hirata on the track  horikita and ayanokouji watch the exchange from the stands  shibata chases down nagumo on the anchor leg  ayanokouji s eyes meet the president s instead","h":"<article class=\"card\" id=\"sc-nagumo-miyabi-y1v5-p79-1\"><h3><span class=\"ttl\">Ch.5, Ch.9: passing mentions<\/span><span class=\"meta\">Y1V5 · p.79, 187<\/span><\/h3><p class=\"setup\">Second-year soccer players take a break; Nagumo calls to Hirata on the track.<\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Horikita and Ayanokouji watch the exchange from the stands.<span class=\"pg\">p.79<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Shibata chases down Nagumo on the anchor leg; Ayanokouji’s eyes meet the president’s instead.<span class=\"pg\">p.187<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nagumo-miyabi-y1v5-p68-1\">← Before: Ch.5 §5: The practice pitch<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nagumo-miyabi-y1v5-p183-1\">→ After: Ch.9 §9: the second-year anchor’s politics<\/button><\/div><\/article>"},{"i":"sc-nagumo-miyabi-y1v5-p183-1","v":"y1v5","y":1,"o":6,"k":"spoken","w":"horikita-manabu nagumo-miyabi","q":"nagumo miyabi ch 9  9  the second year anchor s politics nagumo runs the second year anchor leg and tells the student council president he will remake the school as a meritocracy   looks like victory is ours this time  president horikita  i would ve liked to run against you directly  if possible   looks like we re going to win in overall points  too  guess this is the dawn of a new era  eh   you re too traditional  and even though you re strict  you re weak  your rules are too generous  and they stop people from getting expelled  all i m going to do is help make this school the ultimate meritocracy  addresses the president by title while taking the second year anchor baton","h":"<article class=\"card\" id=\"sc-nagumo-miyabi-y1v5-p183-1\"><h3><span class=\"ttl\">Ch.9 §9: the second-year anchor’s politics<\/span><span class=\"meta\">Y1V5 · p.183–185<\/span><\/h3><p class=\"setup\">Nagumo runs the second-year anchor leg and tells the student council president he will remake the school as a meritocracy.<\/p><p class=\"with\">with <a href=\"horikita-manabu.html\">Horikita Manabu<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Looks like victory is ours this time, President Horikita. I would’ve liked to run against you directly, if possible.”<span class=\"pg\">p.184<\/span><\/li><li class=\"q spoken\">“Looks like we’re going to win in overall points, too. Guess this is the dawn of a new era, eh?”<span class=\"pg\">p.184<\/span><\/li><li class=\"q spoken\">“You’re too traditional. And even though you’re strict, you’re weak. Your rules are too generous, and they stop people from getting expelled. All I’m going to do is help make this school the ultimate meritocracy,”<span class=\"pg\">p.185<\/span><\/li><\/ul><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Manabu<\/b> Addresses the president by title while taking the second-year anchor baton.<span class=\"pg\">p.184–185<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nagumo-miyabi-y1v5-p79-1\">← Before: Ch.5, Ch.9: passing mentions<\/button><\/div><\/article>"},{"i":"sc-nagumo-miyabi-y1v6-p14-1","v":"y1v6","y":1,"o":7,"k":"narration spoken","w":"horikita-manabu nagumo-miyabi","q":"nagumo miyabi ch 2  sworn in as student council president second year class a member introduced as the next president  he takes the microphone after horikita manabu s farewell   hello  i m nagumo  second year class a  student council president horikita  i sincerely appreciate the strict yet kind guidance you ve shown me   i d like to express my respect for you  while also emphasizing what an honor it s been to serve alongside the most capable president in this school s history  you ve exhibited the strongest leadership possible   allow me to introduce myself again  my name is nagumo miyabi  and i will be assuming the position of student council president at the tokyo metropolitan advanced nurturing high school  i sincerely look forward to working with all of you  pledges  indefinite officer terms while enrolled  annul october general election  no size cap  open officer intake  majority vote removal   to bring this school into the future  i intend to thoroughly destroy the past  enigmatic during the sports festival  then the picture of politeness   until the reform announcement changes the atmosphere   a revolution is coming  students with real ability will rise to the top  and students without any will fall  i intend to turn this school into a true meritocracy  so please  give me everything you ve got  i look forward to seeing what you can do  glances at horikita while explaining he cannot implement the changes at once as a newly elected president  almost every second year shouts delight  first years do not know the second third year tension behind it","h":"<article class=\"card\" id=\"sc-nagumo-miyabi-y1v6-p14-1\"><h3><span class=\"ttl\">Ch.2: sworn in as student council president<\/span><span class=\"meta\">Y1V6 · p.14–16<\/span><\/h3><p class=\"setup\">Second-year Class A member introduced as the next president; he takes the microphone after Horikita Manabu’s farewell.<\/p><p class=\"with\">with <a href=\"horikita-manabu.html\">Horikita Manabu<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Hello. I’m Nagumo, second-year Class A. Student Council President Horikita, I sincerely appreciate the strict yet kind guidance you’ve shown me.”<span class=\"pg\">p.14<\/span><\/li><li class=\"q spoken\">“I’d like to express my respect for you, while also emphasizing what an honor it’s been to serve alongside the most capable president in this school’s history. You’ve exhibited the strongest leadership possible.”<span class=\"pg\">p.14<\/span><\/li><li class=\"q spoken\">“Allow me to introduce myself again. My name is Nagumo Miyabi, and I will be assuming the position of student council president at the Tokyo Metropolitan Advanced Nurturing High School. I sincerely look forward to working with…”<span class=\"pg\">p.15<\/span><\/li><\/ul><details class=\"more\"><summary>7 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Allow me to introduce myself again. My name is Nagumo Miyabi, and I will be assuming the position of student council president at the Tokyo Metropolitan Advanced Nurturing High School. I sincerely look forward to working with all of you.”<span class=\"pg\">p.15<\/span><\/li><li><span class=\"mlabel\">Rule<\/span> Pledges: indefinite officer terms while enrolled; annul October general election; no size cap; open officer intake; majority-vote removal.<span class=\"pg\">p.15<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “To bring this school into the future, I intend to thoroughly destroy the past.”<span class=\"pg\">p.15<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Enigmatic during the sports festival, then the picture of politeness — until the reform announcement changes the atmosphere.<span class=\"pg\">p.15<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “A revolution is coming. Students with real ability will rise to the top, and students without any will fall. I intend to turn this school into a true meritocracy, so please, give me everything you’ve got. I look forward to seeing what you can do.”<span class=\"pg\">p.16<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Manabu<\/b> Glances at Horikita while explaining he cannot implement the changes at once as a newly elected president.<span class=\"pg\">p.15<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> Almost every second-year shouts delight; first years do not know the second/third-year tension behind it.<span class=\"pg\">p.16<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nagumo-miyabi-y1v6-p70-1\">→ After: Ch.4: contrasted with Ryuuen’s violence<\/button><\/div><\/article>"},{"i":"sc-nagumo-miyabi-y1v6-p70-1","v":"y1v6","y":1,"o":7,"k":"","w":"horikita-manabu ryuuen-kakeru nagumo-miyabi","q":"nagumo miyabi ch 4  contrasted with ryuuen s violence named as current president in the same contrast with former president horikita  paired with him as the authority style ryuuen wields violence against instead  ryuuen  i will not yield to authority  even if the school tries to expel me    their style is not his  no dialogue or action from nagumo on these pages","h":"<article class=\"card\" id=\"sc-nagumo-miyabi-y1v6-p70-1\"><h3><span class=\"ttl\">Ch.4: contrasted with Ryuuen’s violence<\/span><span class=\"meta\">Y1V6 · p.70<\/span><\/h3><p class=\"setup\">Named as current president in the same contrast with former-president Horikita.<\/p><p class=\"with\">with <a href=\"horikita-manabu.html\">Horikita Manabu<\/a> · <a href=\"ryuuen-kakeru.html\">Ryūen Kakeru<\/a><\/p><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Manabu<\/b> Paired with him as the authority style Ryuuen wields violence against instead.<span class=\"pg\">p.70<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> Ryuuen: I will not yield to authority. Even if the school tries to expel me… — their style is not his.<span class=\"pg\">p.70<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> No dialogue or action from Nagumo on these pages.<span class=\"pg\">p.70<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nagumo-miyabi-y1v6-p14-1\">← Before: Ch.2: sworn in as student council president<\/button><\/div><\/article>"},{"i":"sc-nagumo-miyabi-y1v7-p87-1","v":"y1v7","y":1,"o":8,"k":"","w":"horikita-manabu ichinose-honami katsuragi-kouhei ayanokouji-kiyotaka nagumo-miyabi","q":"nagumo miyabi ch 3  named through manabu the subject of manabu s dorm room warning   failed successor  council hijacker  coming expulsions  second year class a  current student council president  ayanokoji only exchanged pleasantries at the sports festival  ideologies differed from manabu s  almost all second year students under his sway   already won over the entire school  worked behind manabu to contact ichinose and force her onto the council  the successor who went wrong  the man manabu watches  the first year he snatched onto the council  the other applicant manabu refused to protect them both  warned about him  still declines the student council game","h":"<article class=\"card\" id=\"sc-nagumo-miyabi-y1v7-p87-1\"><h3><span class=\"ttl\">Ch.3: named through Manabu<\/span><span class=\"meta\">Y1V7 · p.87–89<\/span><\/h3><p class=\"setup\">The subject of Manabu’s dorm-room warning — failed successor, council hijacker, coming expulsions.<\/p><p class=\"with\">with <a href=\"horikita-manabu.html\">Horikita Manabu<\/a> · <a href=\"ichinose-honami.html\">Ichinose Honami<\/a> · <a href=\"katsuragi-kouhei.html\">Katsuragi Kōhei<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><details class=\"more\"><summary>7 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Second-year Class A, current student council president; Ayanokōji only exchanged pleasantries at the sports festival.<span class=\"pg\">p.87<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Ideologies differed from Manabu’s; almost all second-year students under his sway; “already won over the entire school.”<span class=\"pg\">p.87<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Worked behind Manabu to contact Ichinose and force her onto the council.<span class=\"pg\">p.88<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Manabu<\/b> The successor who went wrong; the man Manabu watches.<span class=\"pg\">p.87–89<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> The first-year he snatched onto the council.<span class=\"pg\">p.88<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Katsuragi Kōhei<\/b> The other applicant Manabu refused to protect them both.<span class=\"pg\">p.87<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Warned about him; still declines the student-council game.<span class=\"pg\">p.87–89<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-nagumo-miyabi-y1v7_5-p86-1","v":"y1v7.5","y":1,"o":9,"k":"spoken","w":"horikita-manabu horikita-suzune nagumo-miyabi","q":"nagumo miyabi ch 4  the target of the debt named as the new student council president whose way horikita manabu wants stopped   nagumo s just tryin  to make this shitty  boring ass school into something fun  from the sound of it    speaker is ryuuen  nagumo does not speak in ch4  the debt ayanokoji owes is to stop him  manabu prepared student council briefs  if suzune joins the student council  manabu would cooperate   a nagumo adjacent lever  seventeen second year expulsions already  involved in over half the cases per exit interviews","h":"<article class=\"card\" id=\"sc-nagumo-miyabi-y1v7_5-p86-1\"><h3><span class=\"ttl\">Ch.4: the target of the debt<\/span><span class=\"meta\">Y1V7.5 · p.86–92<\/span><\/h3><p class=\"setup\">Named as the new student council president whose way Horikita Manabu wants stopped.<\/p><p class=\"with\">with <a href=\"horikita-manabu.html\">Horikita Manabu<\/a> · <a href=\"horikita-suzune.html\">Horikita Suzune<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Nagumo’s just tryin’ to make this shitty, boring-ass school into something fun, from the sound of it.” — speaker is Ryuuen; Nagumo does not speak in ch4.<span class=\"pg\">p.88<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Manabu<\/b> The debt Ayanokōji owes is to stop him; Manabu prepared student-council briefs.<span class=\"pg\">p.86–92<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> If Suzune joins the student council, Manabu would cooperate — a Nagumo-adjacent lever.<span class=\"pg\">p.92<\/span><\/li><li><span class=\"mlabel\">Feat<\/span> Seventeen second-year expulsions already; involved in over half the cases per exit interviews.<span class=\"pg\">p.88<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nagumo-miyabi-y1v7_5-p123-1\">→ After: Ch.5: the arm-grab and the online-game tease<\/button><\/div><\/article>"},{"i":"sc-nagumo-miyabi-y1v7_5-p123-1","v":"y1v7.5","y":1,"o":9,"k":"spoken","w":"ayanokouji-kiyotaka horikita-manabu hirata-yousuke ichinose-honami nagumo-miyabi","q":"nagumo miyabi ch 5  the arm grab and the online game tease interrupts the double date outside the theater with kiriyama  mizowaki  tonokawa and ichinose  grabs ayanokoji s arm   you re the student horikita senpai s been so fixated on  i m just following the rumors  is all   former student council president  after he graduates  i have a whole year at this school  won t you play with me   i imagine that you first years have had some shitty  boring tests so far  what if we had a special test based on a popular online game   sorry for pushing in on your date  see ya around  targets him because manabu talks to him  the mystery second year is about stopping him  rival  manabu s influence on ayanokoji  doesn t sit well  soccer club under him  people who butted heads quit and dropped out  walks with his entourage  gentle smile at ayanokoji  grabs ayanokoji s arm without letting go while smiling amiably","h":"<article class=\"card\" id=\"sc-nagumo-miyabi-y1v7_5-p123-1\"><h3><span class=\"ttl\">Ch.5: the arm-grab and the online-game tease<\/span><span class=\"meta\">Y1V7.5 · p.123–126, 131–132, 145, 149, 151–153<\/span><\/h3><p class=\"setup\">Interrupts the double date outside the theater with Kiriyama, Mizowaki, Tonokawa and Ichinose; grabs Ayanokōji’s arm.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"horikita-manabu.html\">Horikita Manabu<\/a> · <a href=\"hirata-yousuke.html\">Hirata Yōsuke<\/a> · <a href=\"ichinose-honami.html\">Ichinose Honami<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“You’re the student Horikita-senpai’s been so fixated on. I’m just following the rumors, is all.”<span class=\"pg\">p.124<\/span><\/li><li class=\"q spoken\">“Former student council president. After he graduates, I have a whole year at this school. Won’t you play with me?”<span class=\"pg\">p.125<\/span><\/li><li class=\"q spoken\">“I imagine that you first years have had some shitty, boring tests so far… What if we had a special test based on a popular online game?”<span class=\"pg\">p.126<\/span><\/li><\/ul><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Sorry for pushing in on your date. See ya around.”<span class=\"pg\">p.126<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Targets him because Manabu talks to him; the mystery second year is about stopping him.<span class=\"pg\">p.123–126, 145, 151–153<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Manabu<\/b> Rival; Manabu’s influence on Ayanokōji “doesn’t sit well.”<span class=\"pg\">p.125, 151–153<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hirata Yōsuke<\/b> Soccer club under him; people who butted heads quit and dropped out.<span class=\"pg\">p.123–126, 131–132<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> Walks with his entourage; gentle smile at Ayanokōji.<span class=\"pg\">p.123<\/span><\/li><li><span class=\"mlabel\">Feat<\/span> Grabs Ayanokōji’s arm without letting go while smiling amiably.<span class=\"pg\">p.125<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nagumo-miyabi-y1v7_5-p86-1\">← Before: Ch.4: the target of the debt<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nagumo-miyabi-y1v7_5-p149-1\">→ After: Ch.5: named in the threat list<\/button><\/div><\/article>"},{"i":"sc-nagumo-miyabi-y1v7_5-p149-1","v":"y1v7.5","y":1,"o":9,"k":"","w":"nagumo-miyabi","q":"nagumo miyabi ch 5  named in the threat list named once in ayanokoji s honeypot math as a threat who would not crumble karuizawa now  passing mention   if ryuuen  or sakayanagi  or even someone like nagumo approached her  she wouldn t crumble","h":"<article class=\"card\" id=\"sc-nagumo-miyabi-y1v7_5-p149-1\"><h3><span class=\"ttl\">Ch.5: named in the threat list<\/span><span class=\"meta\">Y1V7.5 · p.149<\/span><\/h3><p class=\"setup\">Named once in Ayanokōji’s honeypot math as a threat who would not crumble Karuizawa now.<\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Passing mention: “If Ryuuen, or Sakayanagi, or even someone like Nagumo approached her, she wouldn’t crumble.”<span class=\"pg\">p.149<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nagumo-miyabi-y1v7_5-p123-1\">← Before: Ch.5: the arm-grab and the online-game tease<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nagumo-miyabi-y1v7_5-p155-1\">→ After: Ch.6: the enemy Kiriyama describes<\/button><\/div><\/article>"},{"i":"sc-nagumo-miyabi-y1v7_5-p155-1","v":"y1v7.5","y":1,"o":9,"k":"","w":"kiriyama-ikuto ayanokouji-kiyotaka nagumo-miyabi","q":"nagumo miyabi ch 6  the enemy kiriyama describes discussed throughout the kiriyama meet  not present  passing mention  kiriyama never agreed with nagumo  nagumo s reform pitch of promoting capable students regardless of class  passing mention  almost all second years under nagumo  dissatisfied but not enough votes  persons of interest list starts third semester  anyone on his bad side expelled across the board  passing mention  ayanokoji s risk model   dirty play could get people expelled  sudou ishizaki fight as example  the regime kiriyama infiltrates and wants removed from office  already on the radar after the relay  ayanokoji weighs pretending the relay was a fluke","h":"<article class=\"card\" id=\"sc-nagumo-miyabi-y1v7_5-p155-1\"><h3><span class=\"ttl\">Ch.6: the enemy Kiriyama describes<\/span><span class=\"meta\">Y1V7.5 · p.155–159, 161–162<\/span><\/h3><p class=\"setup\">Discussed throughout the Kiriyama meet; not present.<\/p><p class=\"with\">with <a href=\"kiriyama-ikuto.html\">Kiriyama Ikuto<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Passing mention: Kiriyama never agreed with Nagumo; Nagumo’s reform pitch of promoting capable students regardless of class.<span class=\"pg\">p.155<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Passing mention: almost all second-years under Nagumo; dissatisfied but not enough votes; persons-of-interest list starts third semester; anyone on his bad side expelled across the board.<span class=\"pg\">p.156–158<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Passing mention: Ayanokōji’s risk model — dirty play could get people expelled (Sudou/Ishizaki fight as example).<span class=\"pg\">p.161–162<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kiriyama Ikuto<\/b> The regime Kiriyama infiltrates and wants removed from office.<span class=\"pg\">p.155–159<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Already on the radar after the relay; Ayanokōji weighs pretending the relay was a fluke.<span class=\"pg\">p.157–162<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nagumo-miyabi-y1v7_5-p149-1\">← Before: Ch.5: named in the threat list<\/button><\/div><\/article>"},{"i":"sc-nagumo-miyabi-y1v8-p10-1","v":"y1v8","y":1,"o":10,"k":"","w":"horikita-manabu nagumo-miyabi","q":"nagumo miyabi ch 1  named as the bulldozer named in manabu s graduation soliloquy as the one who took direct action to clear him from the path  passing mention   nagumo miyabi continues to take direct action against me     perhaps  a bulldozer  is the description that fits him best  pressed manabu for three years  manabu had given up responding before graduation","h":"<article class=\"card\" id=\"sc-nagumo-miyabi-y1v8-p10-1\"><h3><span class=\"ttl\">Ch.1: named as the bulldozer<\/span><span class=\"meta\">Y1V8 · p.10<\/span><\/h3><p class=\"setup\">Named in Manabu’s graduation soliloquy as the one who took direct action to clear him from the path.<\/p><p class=\"with\">with <a href=\"horikita-manabu.html\">Horikita Manabu<\/a><\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Passing mention: “Nagumo Miyabi continues to take direct action against me” — “Perhaps ‘a bulldozer’ is the description that fits him best.”<span class=\"pg\">p.10<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Manabu<\/b> Pressed Manabu for three years; Manabu had given up responding before graduation.<span class=\"pg\">p.10<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nagumo-miyabi-y1v8-p11-1\">→ After: Ch.2: named as the grade-level thread to watch<\/button><\/div><\/article>"},{"i":"sc-nagumo-miyabi-y1v8-p11-1","v":"y1v8","y":1,"o":10,"k":"","w":"ayanokouji-kiyotaka nagumo-miyabi","q":"nagumo miyabi ch 2  named as the grade level thread to watch not on the bus or in the gym  named once in ayanokoji s protection planning as the exam opens  passing mention  given the rare chance for grade levels to intermingle  ayanokoji resolves to keep an eye on nagumo s movements  outside thread ayanokoji flags while listing who he will and will not protect","h":"<article class=\"card\" id=\"sc-nagumo-miyabi-y1v8-p11-1\"><h3><span class=\"ttl\">Ch.2: named as the grade-level thread to watch<\/span><span class=\"meta\">Y1V8 · p.11–43<\/span><\/h3><p class=\"setup\">Not on the bus or in the gym; named once in Ayanokōji’s protection planning as the exam opens.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Passing mention: given the rare chance for grade levels to intermingle, Ayanokōji resolves to keep an eye on Nagumo’s movements.<span class=\"pg\">p.32<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Outside thread Ayanokōji flags while listing who he will and will not protect.<span class=\"pg\">p.32<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nagumo-miyabi-y1v8-p10-1\">← Before: Ch.1: named as the bulldozer<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nagumo-miyabi-y1v8-p52-1\">→ After: Ch.2: the early draft, the duel, and Kōenji’s bust<\/button><\/div><\/article>"},{"i":"sc-nagumo-miyabi-y1v8-p52-1","v":"y1v8","y":1,"o":10,"k":"spoken","w":"horikita-manabu fujimaki kouenji-rokusuke yukimura-teruhiko ayanokouji-kiyotaka nagumo-miyabi","q":"nagumo miyabi ch 2  the early draft  the duel  and koenji s bust after first year small groups finish  nagumo moves the large group draft forward and then presses ayanokoji s delayed group for a representative   how about we form a large group right now   should we have a draft pick system  brief private talk with the former president  then the public challenge   fujimaki interrupts  but nagumo forces the average score duel with anti collateral conditions   how about which of us can get the most students expelled   how about which group can earn the higher average score  taunts fujimaki as third year class a s number two and invites him to be the opponent instead of horikita  exposes koenji s twenty million point class a purchase plan  warns the second  and third years off dealing with him  and says he will report pre graduation point purchases to the school  deduces the delayed groups from the draft timing  orders the representative chosen now  dismisses the group once yukimura volunteers  reads group composition from a one second delay in the rock paper scissors circle   ayanokoji admits the attempt to hide the weakness failed  calls him out after the draft  ayanokoji notes nagumo may be watching at every meal  top dog of second year class a  second years wear worshipful looks   rival  hated enemy  deeply respected","h":"<article class=\"card\" id=\"sc-nagumo-miyabi-y1v8-p52-1\"><h3><span class=\"ttl\">Ch.2: the early draft, the duel, and Kōenji’s bust<\/span><span class=\"meta\">Y1V8 · p.52–68<\/span><\/h3><p class=\"setup\">After first-year small groups finish, Nagumo moves the large-group draft forward and then presses Ayanokōji’s delayed group for a representative.<\/p><p class=\"with\">with <a href=\"horikita-manabu.html\">Horikita Manabu<\/a> · <a href=\"fujimaki.html\">Fujimaki<\/a> · <a href=\"kouenji-rokusuke.html\">Kōenji Rokusuke<\/a> · <a href=\"yukimura-teruhiko.html\">Yukimura Teruhiko<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“How about we form a large group right now?”<span class=\"pg\">p.52<\/span><\/li><li class=\"q spoken\">“Should we have a draft-pick system?”<span class=\"pg\">p.52<\/span><\/li><li class=\"q spoken\">“How about which of us can get the most students expelled?”<span class=\"pg\">p.59<\/span><\/li><\/ul><details class=\"more\"><summary>8 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Manabu<\/b> Brief private talk with the former president; then the public challenge — Fujimaki interrupts, but Nagumo forces the average-score duel with anti-collateral conditions.<span class=\"pg\">p.53, 57–60<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “how about which group can earn the higher average score?”<span class=\"pg\">p.59<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Fujimaki<\/b> Taunts Fujimaki as third-year Class A’s number two and invites him to be the opponent instead of Horikita.<span class=\"pg\">p.57–58<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kōenji Rokusuke<\/b> Exposes Kōenji’s twenty-million-point Class A purchase plan, warns the second- and third-years off dealing with him, and says he will report pre-graduation point purchases to the school.<span class=\"pg\">p.64–67<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yukimura Teruhiko<\/b> Deduces the delayed groups from the draft timing; orders the representative chosen now; dismisses the group once Yukimura volunteers.<span class=\"pg\">p.61–68<\/span><\/li><li><span class=\"mlabel\">Feat<\/span> Reads group composition from a one-second delay in the rock-paper-scissors circle — Ayanokōji admits the attempt to hide the weakness failed.<span class=\"pg\">p.61<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Calls him out after the draft; Ayanokōji notes Nagumo may be watching at every meal.<span class=\"pg\">p.52, 61<\/span><\/li><li><span class=\"mlabel\">Position<\/span> Top dog of second-year Class A; second-years wear worshipful looks — rival, hated enemy, deeply respected.<span class=\"pg\">p.46–47, 57–58<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nagumo-miyabi-y1v8-p11-1\">← Before: Ch.2: named as the grade-level thread to watch<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nagumo-miyabi-y1v8-p84-1\">→ After: Ch.3: breakfast order, the card visit, the marked deck<\/button><\/div><\/article>"},{"i":"sc-nagumo-miyabi-y1v8-p84-1","v":"y1v8","y":1,"o":10,"k":"spoken","w":"kouenji-rokusuke ayanokouji-kiyotaka ishikura kiriyama-ikuto nagumo-miyabi","q":"nagumo miyabi ch 3  breakfast order  the card visit  the marked deck at the outdoor breakfast as first years accept the rotation  later invades group six s dorm with kiriyama  tsunoda and ishikura for old maid stakes on breakfast duty   yeah  i ve got no objections  i d like to start with the first years   i came to check on you since we re in the same group  can i come in   let s bet on that  if  for example  you lose constantly  you ll be on meal duty until the end of camp   why don t you join the student council  kouenji  i d love to have someone as interesting as you aboard   you must be glad  ayanokouji  looks like you escaped  invites koenji to the student council  takes his foreseen outcome question seriously enough to answer  then shuffles away amiable when koenji declines all of it  never looks at him until he beckons him in for game five  the last two card offer is a marked joker trap ayanokoji walks past by picking the winner  banter about rooms  soccer vs council  and horikita  ishikura brushes the  might get along just fine  line and leaves abruptly  vp finishes second in the early rounds  nagumo s third place finish in round three is played as bad luck  predicts outcomes in a chance game  holds a sealed box deck he first dealt  the notch on the joker  and still loses the last pick without the marked card being exposed   i d like to leave the first years with three losses  but i m also okay with four    the whole night is a controlled test  not a party","h":"<article class=\"card\" id=\"sc-nagumo-miyabi-y1v8-p84-1\"><h3><span class=\"ttl\">Ch.3: breakfast order, the card visit, the marked deck<\/span><span class=\"meta\">Y1V8 · p.84–109<\/span><\/h3><p class=\"setup\">At the outdoor breakfast as first-years accept the rotation; later invades group six’s dorm with Kiriyama, Tsunoda and Ishikura for Old Maid stakes on breakfast duty.<\/p><p class=\"with\">with <a href=\"kouenji-rokusuke.html\">Kōenji Rokusuke<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"ishikura.html\">Ishikura<\/a> · <a href=\"kiriyama-ikuto.html\">Kiriyama Ikuto<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Yeah. I’ve got no objections. I’d like to start with the first-years.”<span class=\"pg\">p.84<\/span><\/li><li class=\"q spoken\">“I came to check on you since we’re in the same group. Can I come in?”<span class=\"pg\">p.96<\/span><\/li><li class=\"q spoken\">“Let’s bet on that. If, for example, you lose constantly, you’ll be on meal duty until the end of camp.”<span class=\"pg\">p.97<\/span><\/li><\/ul><details class=\"more\"><summary>8 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Why don’t you join the student council, Kouenji? I’d love to have someone as interesting as you aboard.”<span class=\"pg\">p.98<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You must be glad, Ayanokouji. Looks like you escaped.”<span class=\"pg\">p.107<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kōenji Rokusuke<\/b> Invites Kōenji to the student council, takes his foreseen-outcome question seriously enough to answer, then shuffles away amiable when Kōenji declines all of it.<span class=\"pg\">p.98, 105–106<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Never looks at him until he beckons him in for game five; the last two-card offer is a marked-joker trap Ayanokōji walks past by picking the winner.<span class=\"pg\">p.100, 104, 107–108<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ishikura<\/b> Banter about rooms, soccer vs council, and Horikita; Ishikura brushes the “might get along just fine” line and leaves abruptly.<span class=\"pg\">p.96–109<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kiriyama Ikuto<\/b> VP finishes second in the early rounds; Nagumo’s third-place finish in round three is played as bad luck.<span class=\"pg\">p.100–103<\/span><\/li><li><span class=\"mlabel\">Feat<\/span> Predicts outcomes in a chance game, holds a sealed-box deck he first dealt (the notch on the joker), and still loses the last pick without the marked card being exposed.<span class=\"pg\">p.105–108<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> “I’d like to leave the first-years with three losses. But I’m also okay with four” — the whole night is a controlled test, not a party.<span class=\"pg\">p.104, 106–109<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nagumo-miyabi-y1v8-p52-1\">← Before: Ch.2: the early draft, the duel, and Kōenji’s bust<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nagumo-miyabi-y1v8-p118-1\">→ After: Ch.4: the open offer from the sidelines<\/button><\/div><\/article>"},{"i":"sc-nagumo-miyabi-y1v8-p118-1","v":"y1v8","y":1,"o":10,"k":"spoken","w":"ishikura horikita-manabu kiriyama-ikuto nagumo-miyabi","q":"nagumo miyabi ch 4  the open offer from the sidelines watches kiriyama s confrontation from the sidelines and applauds ishikura s handling   excellent  ishikura senpai  you really got a handle on things  didn t you   the only reason you haven t been able to rise to class a is because there s a genius like horikita manabu in your way  i know you ve fought the good fight for three years  there s a 312 point difference between classes a and b right now   it doesn t matter if he s the representative or not  there are many    ways to crush horikita  said with a laugh  lays out class a and horikita removal plans in front of everyone  gets  i can t trust you  for it  names manabu as the blocker  claims many ways to crush him whether or not he is representative  kiriyama s coaching is the occasion  nagumo watches without intervening until after  guileless or performed show of plans   ayanokoji doubts it was the former  312 point gap between classes a and b at the time of the offer","h":"<article class=\"card\" id=\"sc-nagumo-miyabi-y1v8-p118-1\"><h3><span class=\"ttl\">Ch.4: the open offer from the sidelines<\/span><span class=\"meta\">Y1V8 · p.118–119<\/span><\/h3><p class=\"setup\">Watches Kiriyama’s confrontation from the sidelines and applauds Ishikura’s handling.<\/p><p class=\"with\">with <a href=\"ishikura.html\">Ishikura<\/a> · <a href=\"horikita-manabu.html\">Horikita Manabu<\/a> · <a href=\"kiriyama-ikuto.html\">Kiriyama Ikuto<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Excellent, Ishikura-senpai. You really got a handle on things, didn’t you?”<span class=\"pg\">p.118<\/span><\/li><li class=\"q spoken\">“The only reason you haven’t been able to rise to Class A is because there’s a genius like Horikita Manabu in your way. I know you’ve fought the good fight for three years. There’s a 312-point difference between Classes A and B…”<span class=\"pg\">p.118<\/span><\/li><li class=\"q spoken\">“It doesn’t matter if he’s the representative or not. There are many” — ways to crush Horikita, said with a laugh.<span class=\"pg\">p.119<\/span><\/li><\/ul><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “The only reason you haven’t been able to rise to Class A is because there’s a genius like Horikita Manabu in your way. I know you’ve fought the good fight for three years. There’s a 312-point difference between Classes A and B right now.”<span class=\"pg\">p.118<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ishikura<\/b> Lays out Class A and Horikita-removal plans in front of everyone; gets “I can’t trust you” for it.<span class=\"pg\">p.118–119<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Manabu<\/b> Names Manabu as the blocker; claims many ways to crush him whether or not he is representative.<span class=\"pg\">p.118–119<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kiriyama Ikuto<\/b> Kiriyama’s coaching is the occasion; Nagumo watches without intervening until after.<span class=\"pg\">p.118<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Guileless-or-performed show of plans — Ayanokōji doubts it was the former.<span class=\"pg\">p.119<\/span><\/li><li><span class=\"mlabel\">Numbers<\/span> 312-point gap between Classes A and B at the time of the offer.<span class=\"pg\">p.118<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nagumo-miyabi-y1v8-p84-1\">← Before: Ch.3: breakfast order, the card visit, the marked deck<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nagumo-miyabi-y1v8-p146-1\">→ After: Ch.4: named in the corridor assessment<\/button><\/div><\/article>"},{"i":"sc-nagumo-miyabi-y1v8-p146-1","v":"y1v8","y":1,"o":10,"k":"","w":"horikita-manabu ayanokouji-kiyotaka nagumo-miyabi","q":"nagumo miyabi ch 4  named in the corridor assessment not on the page  named throughout manabu s corridor brief to ayanokoji  passing mention in manabu s assessment  nagumo s public average score challenge  underhanded methods  unusually high second year expulsion rate  never broken a promise  the two year student council history is why manabu trusts the no third parties claim  ayanokoji withholds his own nagumo concerns while taking the brief  manabu s group is mostly class a including first years   strong chance to win the test  that is why nagumo s inaction reads as anxiety fuel","h":"<article class=\"card\" id=\"sc-nagumo-miyabi-y1v8-p146-1\"><h3><span class=\"ttl\">Ch.4: named in the corridor assessment<\/span><span class=\"meta\">Y1V8 · p.146<\/span><\/h3><p class=\"setup\">Not on the page; named throughout Manabu’s corridor brief to Ayanokōji.<\/p><p class=\"with\">with <a href=\"horikita-manabu.html\">Horikita Manabu<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Passing mention in Manabu’s assessment: Nagumo’s public average-score challenge, underhanded methods, unusually high second-year expulsion rate, never broken a promise.<span class=\"pg\">p.146<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Manabu<\/b> The two-year student-council history is why Manabu trusts the no-third-parties claim.<span class=\"pg\">p.146<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Ayanokōji withholds his own Nagumo concerns while taking the brief.<span class=\"pg\">p.145–146<\/span><\/li><li><span class=\"mlabel\">Position<\/span> Manabu’s group is mostly Class A including first-years — strong chance to win the test; that is why Nagumo’s inaction reads as anxiety fuel.<span class=\"pg\">p.146<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nagumo-miyabi-y1v8-p118-1\">← Before: Ch.4: the open offer from the sidelines<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nagumo-miyabi-y1v8-p150-1\">→ After: Ch.5: named in the hanging-around rumor<\/button><\/div><\/article>"},{"i":"sc-nagumo-miyabi-y1v8-p150-1","v":"y1v8","y":1,"o":10,"k":"","w":"ichinose-honami nagumo-miyabi","q":"nagumo miyabi ch 5  named in the hanging around rumor not on the page  named when a class a girl raises the student council president rumor  rumor named   people say they see you hanging around with nagumo senpai a lot  just the two of you  ichinose s answer  council work only  not on his radar  no one she likes now  confirmed she worked a lot with him after joining the student council   the grain of truth under the dating rumor","h":"<article class=\"card\" id=\"sc-nagumo-miyabi-y1v8-p150-1\"><h3><span class=\"ttl\">Ch.5: named in the hanging-around rumor<\/span><span class=\"meta\">Y1V8 · p.150<\/span><\/h3><p class=\"setup\">Not on the page; named when a Class A girl raises the student-council-president rumor.<\/p><p class=\"with\">with <a href=\"ichinose-honami.html\">Ichinose Honami<\/a><\/p><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Rumor named: “People say they see you hanging around with Nagumo-senpai a lot, just the two of you…”<span class=\"pg\">p.150<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> Ichinose’s answer: council work only, not on his radar, no one she likes now.<span class=\"pg\">p.150<\/span><\/li><li><span class=\"mlabel\">Position<\/span> Confirmed she worked a lot with him after joining the student council — the grain of truth under the dating rumor.<span class=\"pg\">p.150<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nagumo-miyabi-y1v8-p146-1\">← Before: Ch.4: named in the corridor assessment<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nagumo-miyabi-y1v8-p165-1\">→ After: Ch.6 half 1: named only as the group force<\/button><\/div><\/article>"},{"i":"sc-nagumo-miyabi-y1v8-p165-1","v":"y1v8","y":1,"o":10,"k":"","w":"nagumo-miyabi","q":"nagumo miyabi ch 6 half 1  named only as the group force not on the page in half 1  the ryuuen groups context sits under nagumo s exam design  half 2 develops it  no half 1 dialogue or action   half 2 asahina interview carries his picture","h":"<article class=\"card\" id=\"sc-nagumo-miyabi-y1v8-p165-1\"><h3><span class=\"ttl\">Ch.6 half 1: named only as the group force<\/span><span class=\"meta\">Y1V8 · p.165<\/span><\/h3><p class=\"setup\">Not on the page in half 1; the Ryuuen-groups context sits under Nagumo’s exam design (half 2 develops it).<\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Limit<\/span> No half 1 dialogue or action — half 2 Asahina interview carries his picture.<span class=\"pg\">p.165<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nagumo-miyabi-y1v8-p150-1\">← Before: Ch.5: named in the hanging-around rumor<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nagumo-miyabi-y1v8-p173-1\">→ After: Ch.6 half 2: the picture Asahina draws<\/button><\/div><\/article>"},{"i":"sc-nagumo-miyabi-y1v8-p173-1","v":"y1v8","y":1,"o":10,"k":"","w":"asahina-nazuna horikita-manabu ayanokouji-kiyotaka ishikura nagumo-miyabi","q":"nagumo miyabi ch 6 half 2  the picture asahina draws not on the page  built entirely through ayanokoji s plan and asahina s interview  target of the probe  true intentions toward horikita s brother  asahina  respects horikita senpai  made him a goal  jealous of missing the relay challenge  second years shared bus exam info at his urging  four classes on the way to allies  girls  large group adjusted with members miyabi could count on  tachibana s group has the secretary  asahina  always sticks to his word  no dirty tricks   whoever cares too much is the one who loses  the source of the fair square   care too much picture  deep classmate relationship named  the rival frame   goal  jealousy  and the girls  group irrelevance to their fight  the one probing  reads clues that disappear as a unique strategy vs sakayanagi and ryuuen   ishikura senpai  named as the third year his group met   not assigned  see volume note  public promise of fair square plus shadow manufacturing under investigation   feint or real still open","h":"<article class=\"card\" id=\"sc-nagumo-miyabi-y1v8-p173-1\"><h3><span class=\"ttl\">Ch.6 half 2: the picture Asahina draws<\/span><span class=\"meta\">Y1V8 · p.173–181<\/span><\/h3><p class=\"setup\">Not on the page; built entirely through Ayanokōji’s plan and Asahina’s interview.<\/p><p class=\"with\">with <a href=\"asahina-nazuna.html\">Asahina Nazuna<\/a> · <a href=\"horikita-manabu.html\">Horikita Manabu<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"ishikura.html\">Ishikura<\/a><\/p><details class=\"more\"><summary>10 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Target of the probe: true intentions toward Horikita’s brother.<span class=\"pg\">p.173<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Asahina: respects Horikita-senpai, made him a goal, jealous of missing the relay challenge.<span class=\"pg\">p.176<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Second-years shared bus exam info at his urging; four classes on the way to allies.<span class=\"pg\">p.179<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Girls’ large group adjusted with members Miyabi could count on; Tachibana’s group has the secretary.<span class=\"pg\">p.180<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Asahina: always sticks to his word, no dirty tricks; “whoever cares too much is the one who loses.”<span class=\"pg\">p.181<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Asahina Nazuna<\/b> The source of the fair-square / care-too-much picture; deep classmate relationship named.<span class=\"pg\">p.176–181<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Manabu<\/b> The rival frame — goal, jealousy, and the girls’ group irrelevance to their fight.<span class=\"pg\">p.176, 180–181<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> The one probing; reads clues-that-disappear as a unique strategy vs Sakayanagi and Ryuuen.<span class=\"pg\">p.173–181<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ishikura<\/b> “Ishikura-senpai” named as the third-year his group met — not assigned (see volume note).<span class=\"pg\">p.181<\/span><\/li><li><span class=\"mlabel\">Position<\/span> Public promise of fair square plus shadow-manufacturing under investigation — feint or real still open.<span class=\"pg\">p.181<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nagumo-miyabi-y1v8-p165-1\">← Before: Ch.6 half 1: named only as the group force<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nagumo-miyabi-y1v8-p207-1\">→ After: Ch.7: the abstain demand and the name play<\/button><\/div><\/article>"},{"i":"sc-nagumo-miyabi-y1v8-p207-1","v":"y1v8","y":1,"o":10,"k":"spoken","w":"horikita-manabu ryuuen-kakeru hashimoto-masayoshi ayanokouji-kiyotaka sakayanagi-arisu ichinose-honami nagumo-miyabi","q":"nagumo miyabi ch 7  the abstain demand and the name play interrupts the hashimoto ryuuen meeting with manabu  demands manabu abstain  uses ayanokoji s name on hashimoto   what s up  first years  having a secret meeting at a time like this  huh   i ve heard you re quite the delinquent  your name s ryuuen  right  i m going to have a little chat with horikita senpai  but you should come along   wow  you re confident  not scared of me  ryuuen   heh   i don t dislike people like you   hey  how about you join this wager  as a third party  which group do you think will place higher in today s special exam  mine  or horikita senpai s  how about ten thousand points a head  no matter which side you bet on  i ll pay up if you re right on the money  if you re wrong  though  you gotta pay up   ten thousand is  that kind of money  huh  you re in class d  meaning you re always short on cash  right  can t hurt to earn a little more   hahaha  you re a funny guy  ryuuen  talk about a ballsy joke   hey  you  first year  you think ryuuen can pay that much   if we had our phones  we could check  i wouldn t mind playing along then  too bad   horikita senpai  please abstain from taking the exam tomorrow   that s right   actually  i m being quite serious   it s for your own sake  senpai   sorry  being able to see too far into the future is a curse  anyway  if you don t kindly abstain tomorrow  senpai  you ll regret it  what i m saying is that i m trying to help you  i could just put the hurt on you without warning  but that would just be heartless  wouldn t it   i understand  the rules of our contest are that we have to fight fair and square  without involving any third parties   yes  because abstaining will allow you to get through this with the least amount of damage  senpai  are you aware of the strategic groundwork that i ve laid  no  you aren t  are you  there isn t a single student at this school who can read my thoughts   ah  that s right  if i recall  he s in the same group as that first year  ayanokouji kiyotaka   what do you think  hashimoto  about ayanokouji   i know  right  but horikita senpai here seems to value ayanokouji over all other first years   see  horikita senpai prizes ayanokouji above even sakayanagi  even ryuuen  even ichinose  since you re in the same group as him  i thought you might have noticed something   why is that  senpai  please  i think it s about time you tell me the reason   sorry  senpai  i suppose you re right  my bad  hashimoto  that was a little joke  abstain demand  fair square contest frame   strategic groundwork  name drops ayanokoji at manabu  wager offer  million counter laughed off  told he is not really fit for the student council  pulls him into the corridor triangle  uses him for the ayanokoji value test  emphasized by name as manabu s prized first year above sakayanagi  ryuuen  ichinose  named in the prized first year ranking  same ranking list  playful menace  seeing too far into the future called a curse  serious abstain under the joke  walks out on ryuuen s million  win tomorrow with groundwork laid   least damage path for manabu is abstention","h":"<article class=\"card\" id=\"sc-nagumo-miyabi-y1v8-p207-1\"><h3><span class=\"ttl\">Ch.7: the abstain demand and the name play<\/span><span class=\"meta\">Y1V8 · p.207–211<\/span><\/h3><p class=\"setup\">Interrupts the Hashimoto–Ryuuen meeting with Manabu; demands Manabu abstain; uses Ayanokōji’s name on Hashimoto.<\/p><p class=\"with\">with <a href=\"horikita-manabu.html\">Horikita Manabu<\/a> · <a href=\"ryuuen-kakeru.html\">Ryūen Kakeru<\/a> · <a href=\"hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"sakayanagi-arisu.html\">Sakayanagi Arisu<\/a> · <a href=\"ichinose-honami.html\">Ichinose Honami<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“What’s up, first-years? Having a secret meeting at a time like this, huh?”<span class=\"pg\">p.207<\/span><\/li><li class=\"q spoken\">“I’ve heard you’re quite the delinquent. Your name’s Ryuuen, right? I’m going to have a little chat with Horikita-senpai, but you should come along.”<span class=\"pg\">p.208<\/span><\/li><li class=\"q spoken\">“Wow, you’re confident. Not scared of me, Ryuuen?”<span class=\"pg\">p.208<\/span><\/li><\/ul><details class=\"more\"><summary>28 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Heh.”<span class=\"pg\">p.208<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I don’t dislike people like you.”<span class=\"pg\">p.208<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Hey, how about you join this wager, as a third party? Which group do you think will place higher in today’s special exam, mine, or Horikita-senpai’s? How about ten thousand points a head? No matter which side you bet on, I’ll pay up if you’re right on the money. If you’re wrong, though, you gotta pay up.”<span class=\"pg\">p.208<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Ten thousand is ‘that kind of money’, huh? You’re in Class D, meaning you’re always short on cash, right? Can’t hurt to earn a little more.”<span class=\"pg\">p.208<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Hahaha! You’re a funny guy, Ryuuen. Talk about a ballsy joke.”<span class=\"pg\">p.208<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Hey, you. First-year. You think Ryuuen can pay that much?”<span class=\"pg\">p.209<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If we had our phones, we could check. I wouldn’t mind playing along then. Too bad.”<span class=\"pg\">p.209<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Horikita-senpai. Please abstain from taking the exam tomorrow”<span class=\"pg\">p.209<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That’s right.”<span class=\"pg\">p.209<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Actually, I’m being quite serious.”<span class=\"pg\">p.209<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s for your own sake, senpai.”<span class=\"pg\">p.209<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Sorry. Being able to see too far into the future is a curse. Anyway, if you don’t kindly abstain tomorrow, senpai, you’ll regret it. What I’m saying is that I’m trying to help you. I could just put the hurt on you without warning, but that would just be heartless, wouldn’t it?”<span class=\"pg\">p.209<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I understand. The rules of our contest are that we have to fight fair and square, without involving any third parties.”<span class=\"pg\">p.209<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yes. Because abstaining will allow you to get through this with the least amount of damage, senpai. Are you aware of the strategic groundwork that I’ve laid? No, you aren’t, are you? There isn’t a single student at this school who can read my thoughts.”<span class=\"pg\">p.210<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Ah, that’s right. If I recall, he’s in the same group as that first-year. Ayanokouji Kiyotaka.”<span class=\"pg\">p.210<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What do you think, Hashimoto? About Ayanokouji.”<span class=\"pg\">p.210<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I know, right? But Horikita-senpai here seems to value Ayanokouji over all other first-years.”<span class=\"pg\">p.210<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “See, Horikita-senpai prizes Ayanokouji above even Sakayanagi, even Ryuuen, even Ichinose. Since you’re in the same group as him, I thought you might have noticed something.”<span class=\"pg\">p.210<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Why is that, senpai? Please, I think it’s about time you tell me the reason.”<span class=\"pg\">p.210<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Sorry, senpai. I suppose you’re right. My bad, Hashimoto. That was a little joke.”<span class=\"pg\">p.211<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Manabu<\/b> Abstain demand; fair-square contest frame; “strategic groundwork”; name-drops Ayanokōji at Manabu.<span class=\"pg\">p.207–211<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> Wager offer; million counter laughed off; told he is not really fit for the student council.<span class=\"pg\">p.208–209<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hashimoto Masayoshi<\/b> Pulls him into the corridor triangle; uses him for the Ayanokōji-value test.<span class=\"pg\">p.207–211<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Emphasized by name as Manabu’s prized first-year above Sakayanagi, Ryuuen, Ichinose.<span class=\"pg\">p.210<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> Named in the prized-first-year ranking.<span class=\"pg\">p.210<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> Same ranking list.<span class=\"pg\">p.210<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Playful menace; seeing too far into the future called a curse; serious abstain under the joke; walks out on Ryuuen’s million.<span class=\"pg\">p.208–211<\/span><\/li><li><span class=\"mlabel\">Goal<\/span> Win tomorrow with groundwork laid — least damage path for Manabu is abstention.<span class=\"pg\">p.209–210<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nagumo-miyabi-y1v8-p173-1\">← Before: Ch.6 half 2: the picture Asahina draws<\/button><\/div><\/article>"}];
